create table veranolink.vl_sources (
    id_vl_source              number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment
    by 1 cache 20 noorder nocycle nokeep noscale not null enable,
    id_vl_company_application number,
    source_url                varchar2(1000 char),
    source_authentication     varchar2(1000 char),
    id_vl_ws_type             number,
    created_date              timestamp(6) default systimestamp,
    id_vl_type_environment    number,
    vl_source_state           number default 0
);

alter table veranolink.vl_sources
    add constraint vl_sources_pk primary key ( id_vl_source )
        using index enable;


